	/**
	 * Default Constructor
	 */
    public DistributorService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new DistributorEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(DistributorRepository.class) );
		this.validator		= applicationContext.getBean(DistributorValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Distributor
	 */
		public Distributor createDistributor( CreateDistributorCommand command ) {

		Distributor entity = new Distributor();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setDistributorId( command.getDistributorId() );
            entity.setName( command.getName() );
            entity.setLicenseNumber( command.getLicenseNumber() );
            entity.setRegion( command.getRegion() );
            entity.setDistributorType( command.getDistributorType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Distributor {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateDistributorCommand
	 * @return		Distributor
	 */
	public Distributor updateDistributor( UpdateDistributorCommand command ) {

		Distributor entity = new Distributor();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setDistributorId( command.getDistributorId() );
            entity.setName( command.getName() );
            entity.setLicenseNumber( command.getLicenseNumber() );
            entity.setRegion( command.getRegion() );
            entity.setInsurers( command.getInsurers() );
            entity.setAgents( command.getAgents() );
            entity.setPolicies( command.getPolicies() );
            entity.setDistributorType( command.getDistributorType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Distributor {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteDistributorCommand
	 */
	public void delete( DeleteDistributorCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getDistributorId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Distributor {0} ", id );

	}

	/**
	 * Method to retrieve the Distributor via DistributorFetchOneSummary
	 * @param 	summary DistributorFetchOneSummary
	 * @return 	DistributorFetchOneResponse
	 */
	public Distributor getDistributor( DistributorFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "DistributorFetchOneSummary arg cannot be null" );

		Distributor entity = null;
		UUID id = summary.getDistributorId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Distributor using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Distributors
	 *
	 * @return 	List<Distributor>
	 */
    public List<Distributor> getAllDistributor() {
		List<Distributor> list = projector.findAll( new FindAllDistributorQuery() );
		return list;
	}


	/**
	 * add Insurer to Insurers
	 * @param		command AssignInsurersToDistributorCommand
	 */
